import fs from 'fs';
import path from 'path';
import { Command } from 'commander';
import express from 'express';
import { Matrix } from 'ml-matrix';
import ndjson from 'ndjson';
import { EmbeddingOutput } from '../types';

interface CorrelationData {
    matrix: number[][];
    rowLabels: string[];
    colLabels: string[];
    rowFull: string[];
    colFull: string[];
    rowFile: string;
    colFile: string;
}

function cosineSimilarity(a: number[], b: number[]): number {
    const dotProduct = a.reduce((sum, val, i) => sum + val * b[i], 0);
    const normA = Math.sqrt(a.reduce((sum, val) => sum + val * val, 0));
    const normB = Math.sqrt(b.reduce((sum, val) => sum + val * val, 0));
    return dotProduct / (normA * normB);
}

function computeCorrelationMatrix(embeddings1: number[][], embeddings2: number[][]): number[][] {
    const matrix = new Matrix(embeddings1.length, embeddings2.length);

    for (let i = 0; i < embeddings1.length; i++) {
        for (let j = 0; j < embeddings2.length; j++) {
            matrix.set(i, j, cosineSimilarity(embeddings1[i], embeddings2[j]));
        }
    }

    return matrix.to2DArray();
}

function isImagePath(str: string): boolean {
    return str.startsWith('data:image/') ||
        str.startsWith('http://') ||
        str.startsWith('https://') ||
        str.endsWith('.jpg') ||
        str.endsWith('.jpeg') ||
        str.endsWith('.png') ||
        str.endsWith('.gif') ||
        str.endsWith('.webp');
}

function resolveImagePath(filePath: string, baseDir: string): string {
    if (filePath.startsWith('data:image/') || filePath.startsWith('http://') || filePath.startsWith('https://')) {
        return filePath;
    }

    // Handle relative paths
    const fullPath = path.resolve(baseDir, filePath);
    if (fs.existsSync(fullPath)) {
        // Convert to data URI for local files
        const mimeType = path.extname(fullPath).toLowerCase() === '.png' ? 'image/png' : 'image/jpeg';
        const imageBuffer = fs.readFileSync(fullPath);
        return `data:${mimeType};base64,${imageBuffer.toString('base64')}`;
    }

    return filePath;
}

async function loadEmbeddings(filePath: string, model: string): Promise<{ embeddings: number[][], chunks: string[] }> {
    return new Promise((resolve, reject) => {
        const embeddings: number[][] = [];
        const chunks: string[] = [];
        const baseDir = path.dirname(filePath);

        fs.createReadStream(filePath)
            .pipe(ndjson.parse())
            .on('data', (obj: EmbeddingOutput) => {
                embeddings.push(obj.embedding);
                // Resolve image paths if the chunk is an image
                const chunk = isImagePath(obj.chunk) ? resolveImagePath(obj.chunk, baseDir) : obj.chunk;
                chunks.push(chunk);
            })
            .on('end', () => resolve({ embeddings, chunks }))
            .on('error', reject);
    });
}

function truncateLabel(text: string, maxLen = 32): string {
    if (isImagePath(text)) {
        return '🖼️'; // Use an emoji to indicate image
    }
    return text.length > maxLen ? text.slice(0, maxLen) + '…' : text;
}

function generateHTML(data: CorrelationData): string {
    const templatePath = path.join(__dirname, `../templates/correlation_d3.html`);
    const template = fs.readFileSync(templatePath, 'utf-8');
    return template.replace('{{ DATA }}', JSON.stringify(data));
}

async function main() {
    const program = new Command();

    program
        .name('corr')
        .description('Compute and visualize correlations between embeddings')
        .argument('<file1>', 'First JSONL file with embeddings')
        .argument('[file2]', 'Second JSONL file with embeddings (optional)')
        .option('-p, --port <number>', 'Port for the visualization server', '3000')
        .option('-m, --model <string>', 'Embedding model to use', 'jina-embeddings-v3')
        .parse(process.argv);

    const options = program.opts();
    const [file1, file2] = program.args;

    try {
        console.log('Loading embeddings...');
        const { embeddings: embeddings1, chunks: chunks1 } = await loadEmbeddings(file1, options.model);

        let embeddings2: number[][];
        let chunks2: string[];

        if (file2) {
            const result = await loadEmbeddings(file2, options.model);
            embeddings2 = result.embeddings;
            chunks2 = result.chunks;
        } else {
            embeddings2 = embeddings1;
            chunks2 = chunks1;
        }

        console.log('Computing correlation matrix...');
        const matrix = computeCorrelationMatrix(embeddings1, embeddings2);

        // Truncate labels for axis, keep full for hover
        const rowLabels = chunks1.map(c => truncateLabel(c));
        const colLabels = chunks2.map(c => truncateLabel(c));
        const data: CorrelationData = {
            matrix,
            rowLabels,
            colLabels,
            rowFull: chunks1,
            colFull: chunks2,
            rowFile: path.basename(file1),
            colFile: file2 ? path.basename(file2) : path.basename(file1)
        };

        const app = express();
        const port = parseInt(options.port);

        app.get('/', (req, res) => {
            res.send(generateHTML(data));
        });

        app.listen(port, () => {
            console.log(`Visualization server running at http://localhost:${port}`);
            console.log('Press Ctrl+C to stop the server');
        });
    } catch (error) {
        console.error('Error:', error instanceof Error ? error.message : String(error));
        process.exit(1);
    }
}

if (require.main === module) {
    main().catch(console.error);
}

import fs from 'fs';
import { Command } from 'commander';
import { getEmbeddings } from '../utils/embeddings';
import { ChunkOptions, TaskType } from '../types';
import { readUrl } from '../utils/reader';

function chunkText(text: string, options: ChunkOptions): string[] {
    switch (options.type) {
        case 'newline':
            return text.split('\n').filter(chunk => chunk.trim().length > 0);

        case 'punctuation':
            // Split by common Chinese and English punctuation while preserving them
            return text.split(/(?<=[.!?。！？])/).filter(chunk => chunk.trim().length > 0);

        case 'characters':
            const chunkSize = Number(options.value) || 1000;
            const chunks: string[] = [];
            for (let i = 0; i < text.length; i += chunkSize) {
                chunks.push(text.slice(i, i + chunkSize));
            }
            return chunks;

        case 'regex':
            if (!options.value || typeof options.value !== 'string') {
                throw new Error('Regex pattern is required for regex chunking');
            }
            return text.split(new RegExp(options.value)).filter(chunk => chunk.trim().length > 0);

        default:
            throw new Error('Invalid chunking type');
    }
}

async function main() {
    const program = new Command();

    program
        .name('embed')
        .description('Embed text from a file or URL')
        .argument('<input>', 'Input text file path or URL')
        .option('-c, --chunk <type>', 'Chunking type (newline, punctuation, characters, regex)', 'newline')
        .option('-v, --value <value>', 'Value for chunking (number for characters, regex pattern for regex)')
        .option('-d, --dimensions <number>', 'Embedding dimensions', '1024')
        .option('-l, --late-chunking', 'Enable late chunking')
        .option('-t, --task-type <type>', 'Task type (text-matching, retrieval.passage, retrieval.query)')
        .option('-m, --model <string>', 'Embedding model to use', 'jina-embeddings-v3')
        .option('-o, --output <path>', 'Output JSON file path')
        .parse(process.argv);

    const options = program.opts();
    const input = program.args[0];

    try {
        let text: string;
        let outputPath: string;

        // Check if input is a URL
        if (input.startsWith('http://') || input.startsWith('https://')) {
            const { response } = await readUrl(input);
            text = response.data.content;
            const domain = new URL(input).hostname.replace(/\./g, '-');
            outputPath = options.output || `${domain}.jsonl`;
        } else {
            text = fs.readFileSync(input, 'utf-8');
            outputPath = options.output || `${input.replace(/[^a-zA-Z0-9]/g, '_')}.jsonl`;
        }

        // Parse chunking options
        const chunkOptions: ChunkOptions = {
            type: options.chunk as ChunkOptions['type'],
            value: options.value
        };

        console.log(options);

        // Chunk the text
        const chunks = chunkText(text, chunkOptions);
        console.log(`Chunked text into ${chunks.length} pieces`);

        // Get embeddings
        const { embeddings } = await getEmbeddings(chunks, {
            dimensions: Number(options.dimensions),
            late_chunking: options.lateChunking,
            task: options.taskType,
            model: options.model
        });

        // Write JSON Lines output
        const outputStream = fs.createWriteStream(outputPath, { flags: 'w' });
        for (let i = 0; i < chunks.length; i++) {
            const obj = { chunk: chunks[i], embedding: embeddings[i] };
            outputStream.write(JSON.stringify(obj) + '\n');
        }
        outputStream.end();
        console.log(`Embeddings written to ${outputPath} (JSON Lines format)`);
    } catch (error) {
        console.error('Error:', error instanceof Error ? error.message : String(error));
        process.exit(1);
    }
}

if (require.main === module) {
    main().catch(console.error);
}
